# Validate every expected authored paper and preserve rich mathematical notation.
def clean(v):
 if isinstance(v,str):
  for c in v:assert ord(c)>=32 or c in '\n\r',(repr(v),ord(c))
  return re.sub(r'\$([^$]+)\$',lambda z:'$'+z[1].replace('<','&lt;').replace('>','&gt;')+'$',v)
 if isinstance(v,list):return [clean(x) for x in v]
 if isinstance(v,dict):return {k:clean(x) for k,x in v.items()}
 return v
